export const DEFAULT_LOCATION: LocationConfig = { key: 'indonesia', aliases: [], adm4: '31.71.03.1001', provinceName: 'Indonesia', displayName: 'Indonesia', center: [-2.5489, 118.0149], zoom: 5 };

export function resolveLocationFromPrompt(prompt: string): LocationConfig {
  const loweredPrompt = prompt.toLowerCase();
  let bestMatch: LocationConfig | null = null;
  let bestAliasLen = 0;
  for (const location of LOCATIONS) {
    for (const alias of location.aliases) {
      if (loweredPrompt.includes(alias) && alias.length > bestAliasLen) {
        bestMatch = location;
        bestAliasLen = alias.length;
      }
    }
  }
  return bestMatch || DEFAULT_LOCATION;
}
